import {CATEGORIES,catById,dateKey,parseDay,uuid,money,toCents,classify,validDate,validateRecord,fingerprint,rangeFor,shiftAnchor,inRange,totals,parseBillText,makeDemo} from './ledger.js';
import {recognizeImages} from './ocr.js';
import {isAndroidApp,nativeDeviceInfo,saveWithAndroid} from './native.js';

const PATHS={
  book:'M5 3h13a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V5a2 2 0 0 1 2-2Zm2 0v14M3 18a2 2 0 0 1 2-2h15M11 7h5m-5 4h5',
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  receipt:'M5 3l2 1 2-1 3 1 3-1 2 1 2-1v18l-2-1-2 1-3-1-3 1-2-1-2 1V3Zm4 5h6m-6 4h6m-6 4h4',
  chart:'M4 3v17h17M8 15v-5m5 5V6m5 9v-7',scan:'M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M7 8h10M7 12h10M7 16h6',
  sprout:'M12 21v-9M12 15C5 16 2 11 3 6c6-1 10 3 9 9Zm0-3c0-6 4-10 10-9 1 6-4 10-10 9',settings:'M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1 1-3Zm3 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
  lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Zm-4 9 3 3 5-6',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Zm-3-14c0-4 7-4 7 0 0 3-4 2-4 5m0 4h.01',
  plus:'M12 5v14M5 12h14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',down:'M12 4v16m-6-6 6 6 6-6',up:'M12 20V4m-6 6 6-6 6 6',wallet:'M3 6h17v15H3zM3 6V3h14v3m-1 6h5v5h-5zm2 2h.01',
  bowl:'M3 11h18c0 6-4 10-9 10S3 17 3 11Zm1-4h16M8 3v4m4-4v4m4-4v4',bag:'M5 7h14l2 14H3L5 7Zm3 0V5a4 4 0 0 1 8 0v2m-8 4h.01M16 11h.01',train:'M6 3h12v14H6zM6 10h12M9 3v7m6-7v7M9 14h.01M15 14h.01M8 17l-3 4m11-4 3 4M8 20h8',
  home:'m2 11 10-8 10 8M5 9v12h14V9m-10 12v-8h6v8',game:'M7 8h10c5 0 7 12 3 12l-4-4H8l-4 4C0 20 2 8 7 8Zm1 3v5m-2-3h4m6 0h.01m3-1h.01M12 8V4',heart:'M12 21 3 12C-3 4 7-2 12 5c5-7 15-1 9 7l-9 9Z',
  gift:'M3 8h18v5H3zM5 13v8h14v-8M12 8v13m0-13C2 9 5-2 12 8Zm0 0c10 1 7-10 0 0',swap:'M3 7h17m-5-5 5 5-5 5M21 17H4m5-5-5 5 5 5',dots:'M5 12h.01M12 12h.01M19 12h.01',search:'M21 21l-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',
  close:'m6 6 12 12M6 18 18 6',upload:'M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5',download:'M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4',check:'m5 12 4 4L19 6',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',
  image:'M3 3h18v18H3zM3 17l6-6 5 5 3-3 4 4M15 7h.01',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Zm0-12v7m0-11h.01',calendar:'M3 5h18v16H3zM3 10h18M7 2v6m10-6v6M7 14h2m4 0h2m-8 3h2',cloud:'M6 19a5 5 0 0 1 0-10 7 7 0 0 1 14-1 5 5 0 0 1-1 11H6'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${PATHS[name]||PATHS.dots}"/></svg>`;
const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='qingji-ledger-v1';
let state, storageError=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1 && Array.isArray(saved.records) && saved.records.every(validateRecord)){state={...saved,rules:Array.isArray(saved.rules)?saved.rules:[]};}}
catch{storageError=true;}
if(!state){const demo=makeDemo();state={version:1,records:demo.records,rules:[],budget:500000,demo:true,anchor:demo.anchor};}
let page='overview',mode='month',anchor=state.anchor||dateKey(),query='',categoryFilter='',sourceFilter='',typeFilter='',toastTimer,editType='expense',currentEdit=null,installEvent=null;
let importState=null;
let preferredOcrProfile='auto';try{const savedProfile=localStorage.getItem('qingji-ocr-profile');if(['auto','enhanced'].includes(savedProfile))preferredOcrProfile=savedProfile;}catch{}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('设备存储不可用或已满。请立即导出备份；本次更改仅在当前页面保留。');return false;}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function sourceName(s){return {wechat:'微信支付',alipay:'支付宝',manual:'手动记账',unknown:'待确认'}[s]||'待确认';}
function platform(s){return s==='wechat'?'<span class="platform-logo">微</span>':s==='alipay'?'<span class="platform-logo alipay">支</span>':icon(s==='manual'?'book':'help');}
function categoryOptions(selected){return CATEGORIES.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('');}
function sourceOptions(selected,manual=true){return (manual?['wechat','alipay','manual','unknown']:['wechat','alipay','unknown']).map(s=>`<option value="${s}" ${selected===s?'selected':''}>${sourceName(s)}</option>`).join('');}
const currentRange=()=>rangeFor(mode,anchor);
const periodRecords=()=>state.records.filter(r=>inRange(r,currentRange()));
function rangeLabel(){const d=parseDay(anchor);if(mode==='month')return `${d.getFullYear()} 年 ${d.getMonth()+1} 月`;const r=currentRange();return `${+r.start.slice(5,7)}.${+r.start.slice(8)} – ${+r.end.slice(5,7)}.${+r.end.slice(8)}`;}
function periodBar(){return `<div class="period-bar"><div class="period-picker"><button class="icon-button" data-action="prev" aria-label="上${mode==='month'?'个月':'一周'}">${icon('left')}</button><strong>${rangeLabel()}</strong><button class="icon-button" data-action="next" aria-label="下${mode==='month'?'个月':'一周'}">${icon('right')}</button><button class="today-button" data-action="today">回到本${mode==='month'?'月':'周'}</button></div><div class="segmented" aria-label="统计周期"><button data-mode="week" class="${mode==='week'?'active':''}" aria-pressed="${mode==='week'}">周账单</button><button data-mode="month" class="${mode==='month'?'active':''}" aria-pressed="${mode==='month'}">月账单</button></div></div>`;}
function stats(records){const t=totals(records),expenseCount=records.filter(r=>r.type==='expense').length,incomeCount=records.length-expenseCount;const prev=rangeFor(mode,shiftAnchor(mode,anchor,-1)),pt=totals(state.records.filter(r=>inRange(r,prev)));const delta=pt.expense?Math.round((t.expense-pt.expense)/pt.expense*100):null;return `<div class="stats"><section class="stat-card featured"><div class="stat-label">${icon('up')}总支出</div><div class="stat-decoration">${icon('wallet')}</div><div class="stat-amount"><small>¥</small>${money(t.expense)}</div><div class="stat-foot"><span>共 ${expenseCount} 笔支出</span><span>·</span><em>${delta===null?'每一笔都值得记录':`较上${mode==='week'?'周':'月'} ${delta>0?'+':''}${delta}%`}</em></div></section><section class="stat-card"><div class="stat-label">${icon('down')}总收入</div><div class="stat-decoration">${icon('down')}</div><div class="stat-amount"><small>¥</small>${money(t.income)}</div><div class="stat-foot">共 ${incomeCount} 笔收入<span>·</span>让努力看得见</div></section><section class="stat-card"><div class="stat-label">${icon('wallet')}收支结余</div><div class="stat-decoration">${icon('swap')}</div><div class="stat-amount"><small>¥</small>${money(t.income-t.expense)}</div><div class="stat-foot">收入 − 支出<span>·</span>心中有数，生活有度</div></section></div>`;}
function importBanner(){return `<section class="import-banner"><div class="import-copy"><h2>一张截图，轻松记一笔</h2><p>上传账单截图，自动识别、分类，告别繁琐输入。</p><div class="source-support"><span class="platform-logo">微</span><b>微信支付</b><span class="platform-logo alipay">支</span><b>支付宝</b><i></i><b>支持多张批量导入</b></div></div><svg class="receipt-art" viewBox="0 0 160 120" aria-hidden="true"><ellipse cx="78" cy="107" rx="62" ry="7" fill="#dce5d1"/><g transform="translate(85 54) rotate(15)"><rect x="-26" y="-39" width="59" height="79" rx="6" fill="#d6dfca"/><path d="M-12-22h31m-31 10h22m-22 10h31m-31 15h18" stroke="#afc09f" stroke-width="4" stroke-linecap="round"/></g><g transform="translate(58 60) rotate(-12)"><path d="M-28-44h58v89l-6-4-6 4-6-4-6 4-6-4-6 4-6-4-6 4-6-4V-44" fill="#fffef8" stroke="#d7dfcc"/><rect x="-17" y="-31" width="14" height="14" rx="4" fill="#96b68a"/><path d="M4-26h14M4-20h10m-35 18h36m-36 10h28m-28 10h36" stroke="#d6decd" stroke-width="3" stroke-linecap="round"/><text x="-18" y="35" font-size="12" fill="#6f8b5e" font-family="Arial">¥ 28.50</text></g><circle cx="118" cy="86" r="16" fill="#6e9060"/><path d="m111 86 5 5 9-10" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M125 21v9m-4-4h8M23 17v7m-4-3h8" stroke="#afc19c" stroke-width="2" stroke-linecap="round"/></svg><div class="import-cta"><button class="btn primary" data-action="import">${icon('scan')}截图导入</button><small>识别 → 核对 → 一键入账</small></div></section>`;}
function trend(records){const r=currentRange(),days=[],end=parseDay(r.end);for(let d=parseDay(r.start);d<=end;d.setDate(d.getDate()+1))days.push({date:dateKey(d),amount:records.filter(v=>v.date===dateKey(d)&&v.type==='expense').reduce((a,v)=>a+v.amount,0)});const max=Math.max(...days.map(d=>d.amount),10000);const top=Math.ceil(max/10000)*10000;const w=560,h=154,left=48,right=541,base=144;const points=days.map((d,i)=>[left+i/(days.length-1)*(right-left),base-d.amount/top*115]);let line='';points.forEach(([x,y],i)=>{if(!i)line=`M ${x},${y}`;else{const prev=points[i-1],mid=(prev[0]+x)/2;line+=` C ${mid},${prev[1]} ${mid},${y} ${x},${y}`;}});const area=line+` L ${right},${base} L ${left},${base} Z`;const sum=totals(records).expense,avg=Math.round(sum/days.length);const peak=days.reduce((a,b)=>b.amount>a.amount?b:a,days[0]);return `<section class="panel"><div class="panel-head"><div class="panel-title"><h2>支出趋势</h2><span>看见消费的节奏</span></div><div class="chart-legend"><i class="dot"></i>每日支出</div></div><svg class="trend-chart" viewBox="0 0 ${w} 178" preserveAspectRatio="none" role="img" aria-label="${esc(rangeLabel())}每日支出趋势，日均${money(avg)}元"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#a9bd96" stop-opacity=".28"/><stop offset="1" stop-color="#d4e0c5" stop-opacity=".03"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${left}" y1="${base-v*115}" x2="${right}" y2="${base-v*115}" stroke="#edf0e8" stroke-dasharray="3 5"/><text x="4" y="${base-v*115+3}">${v===0?'0':Math.round(top*v/100)}</text>`).join('')}<path d="${area}" fill="url(#areaFill)"/><path d="${line}" fill="none" stroke="#88a377" stroke-width="2"/>${days.map((d,i)=>i===0||i===days.length-1||i%(mode==='week'?1:5)===0?`<text x="${points[i][0]}" y="169" text-anchor="middle">${mode==='week'?['周日','周一','周二','周三','周四','周五','周六'][parseDay(d.date).getDay()]:`${+d.date.slice(5,7)}/${+d.date.slice(8)}`}</text>`:'').join('')}</svg><div class="chart-foot"><span>日均支出 <strong>¥ ${money(avg)}</strong></span><span>${sum?`最高支出日 ${+peak.date.slice(5,7)} 月 ${+peak.date.slice(8)} 日`:'添加第一笔，开始了解消费习惯'}</span></div></section>`;}
function categoryPanel(records){const expense=records.filter(r=>r.type==='expense'),sum=totals(expense).expense;const cats=CATEGORIES.map(c=>({...c,amount:expense.filter(r=>r.category===c.id).reduce((a,r)=>a+r.amount,0)})).filter(c=>c.amount).sort((a,b)=>b.amount-a.amount);const visible=cats.slice(0,4);if(cats.length>4)visible.push({name:'其他分类',color:'#c5ccb6',amount:cats.slice(4).reduce((a,c)=>a+c.amount,0)});let offset=0;return `<section class="panel"><div class="panel-head"><div class="panel-title"><h2>消费分类</h2><span>每一笔，各有所归</span></div></div><div class="category-body"><div class="donut-wrap"><svg class="donut" viewBox="0 0 120 120" role="img" aria-label="支出分类占比"><circle cx="60" cy="60" r="47" fill="none" stroke="#f0f3e9" stroke-width="12"/>${visible.map(c=>{const len=c.amount/sum*295.31;const out=`<circle cx="60" cy="60" r="47" fill="none" stroke="${c.color}" stroke-width="12" stroke-dasharray="${Math.max(len-3,0)} ${295.31-Math.max(len-3,0)}" stroke-dashoffset="${-offset}"/>`;offset+=len;return out;}).join('')}</svg><div class="donut-center"><span>支出分类</span><strong>${cats.length}<small> 类</small></strong></div></div><div class="category-legend">${visible.length?visible.map(c=>`<div><i class="category-dot" style="background:${c.color}"></i><b>${c.name}</b><em>${Math.round(c.amount/sum*100)}%</em></div>`).join(''):'<div>还没有支出记录</div>'}</div></div></section>`;}
function dayGroup(date,records){const t=totals(records.filter(r=>r.date===date));return `<tr class="day-group"><td colspan="5"><div><strong>${+date.slice(5,7)} 月 ${+date.slice(8)} 日 <span>${['周日','周一','周二','周三','周四','周五','周六'][parseDay(date).getDay()]}</span></strong><small>支出 ${money(t.expense)} · 收入 ${money(t.income)}</small></div></td></tr>`;}
function table(records,full=false){const sorted=[...records].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return `<div class="table-wrap"><table><thead><tr><th>账单明细</th><th>分类</th><th>支付方式</th><th>日期</th><th style="text-align:right">金额</th></tr></thead><tbody>${sorted.map((r,i)=>{const c=catById(r.category);return `${full&&(!i||sorted[i-1].date!==r.date)?dayGroup(r.date,records):''}<tr class="clickable" data-edit="${esc(r.id)}" tabindex="0" role="button" aria-label="编辑${esc(r.merchant)} ${money(r.amount)}元"><td><div class="merchant-cell"><span class="category-icon" style="background:${c.bg};color:${c.color}">${icon(c.icon)}</span><div><div class="merchant-name">${esc(r.merchant)}</div><div class="merchant-note">${esc(r.note||sourceName(r.source))}<span class="mobile-only">${r.date}</span></div></div></div></td><td><span class="category-pill">${c.name}</span></td><td><span class="source-label">${platform(r.source)}${sourceName(r.source)}</span></td><td class="date-cell">${r.date}</td><td class="amount ${r.type==='income'?'income':''}">${r.type==='income'?'+':'−'} ${money(r.amount)}</td></tr>`;}).join('')}</tbody></table></div>${!records.length?`<div class="empty">${icon('receipt')}这段时间还没有账单<br>记下第一笔，让生活有迹可循。<br><button class="btn" data-action="add">${icon('plus')}记一笔</button></div>`:''}${full?`<div class="list-summary"><span>共 ${records.length} 笔账单</span><span>支出 ¥${money(totals(records).expense)} · 收入 ¥${money(totals(records).income)}</span></div>`:''}`;}
function heading(){const titles={overview:['YOUR EVERYDAY, IN BALANCE','生活有迹，花销有数。','从每一笔小记录开始，慢慢靠近理想的生活。'],bills:['A LITTLE RECORD OF LIFE','每一笔，都有迹可循。','整理生活里的点滴收支，把账本留给自己。'],statistics:['KNOW YOUR SPENDING','读懂花销，安排生活。','看看钱花在了哪里，也看看生活的小小变化。']};const t=titles[page];return `<div class="heading"><div><div class="eyebrow">${t[0]}</div><h1>${t[1]}</h1><p>${t[2]}</p></div><div class="heading-actions"><button class="btn" data-action="export-csv">${icon('download')}导出账单</button><button class="btn primary" data-action="add">${icon('plus')}记一笔</button></div></div>`;}
function render(){const names={overview:'账本总览',bills:'全部账单',statistics:'统计分析'};page=location.hash.slice(1) in names?location.hash.slice(1):'overview';$('#breadcrumb').textContent=names[page];document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const records=periodRecords();let body=heading();if(state.demo)body+=`<div class="demo-banner">${icon('info')}当前为示例账本，数据仅供体验<button data-action="start">开始我的账本 ${icon('right')}</button></div>`;body+=periodBar()+stats(records);if(page==='overview'){body+=importBanner()+`<div class="dashboard-grid">${trend(records)}${categoryPanel(records)}</div><section class="panel transactions"><div class="panel-head"><div class="panel-title"><h2>最近账单</h2><span>生活里的每一个小瞬间</span></div><a href="#bills" class="text-link">查看全部 ${icon('right')}</a></div>${table([...records].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))}</section>`;}else if(page==='bills'){body+=`<section class="panel transactions"><div class="filter-bar"><label class="search-field">${icon('search')}<input id="search" aria-label="搜索商户或备注" placeholder="搜索商户、备注…" value="${esc(query)}"></label><select id="filter-type" aria-label="收支类型"><option value="">全部收支</option value="expense" ${typeFilter==='expense'?'selected':''}>支出</option><option value="income" ${typeFilter==='income'?'selected':''}>收入</option></select><select id="filter-category" aria-label="消费分类"><option value="">全部分类</option>${categoryOptions(categoryFilter)}</select><select id="filter-source" aria-label="支付方式"><option value="">全部支付方式</option>${sourceOptions(sourceFilter)}</select></div><div id="bill-results">${filteredTable(records)}</div></section>`;}else{const rankings=Object.entries(records.filter(r=>r.type==='expense').reduce((a,r)=>{a[r.merchant]=(a[r.merchant]||0)+r.amount;return a;},{})).sort((a,b)=>b[1]-a[1]).slice(0,5);const monthly=totals(state.records.filter(r=>inRange(r,rangeFor('month',anchor)))).expense,budget=state.budget||500000;body+=`<div class="dashboard-grid">${trend(records)}${categoryPanel(records)}</div><div class="analysis-bottom"><section class="panel"><div class="panel-head"><h2>常去的地方</h2><span class="chart-legend">按支出排序</span></div><div class="ranking">${rankings.length?rankings.map(([name,amount],i)=>`<div class="ranking-row"><span class="ranking-number">0${i+1}</span><span>${esc(name)}</span><strong>¥ ${money(amount)}</strong></div>`).join(''):'<div class="empty">还没有消费记录</div>'}</div></section><section class="panel"><div class="panel-head"><h2>${+anchor.slice(5,7)} 月预算</h2><button class="text-link" data-action="budget">调整预算 ${icon('right')}</button></div><div class="budget-body"><div class="budget-amount">¥ ${money(monthly)} <small>/ ¥ ${money(budget)}</small></div><div class="progress-track ${monthly>budget?'over':''}"><span style="width:${Math.min(100,monthly/budget*100)}%"></span></div><p>已使用月预算的 ${Math.round(monthly/budget*100)}%<br>${monthly>budget?`已超出 ¥ ${money(monthly-budget)}，下次消费前，给自己一点思考的时间。`:`还可支出 ¥ ${money(budget-monthly)}，把钱花在真正喜欢的事上。`}</p></div></section></div>`;}
$('#main').innerHTML=body;}
function filteredTable(records){return table(records.filter(r=>(!query||(r.merchant+' '+r.note).toLowerCase().includes(query.toLowerCase()))&&(!typeFilter||r.type===typeFilter)&&(!categoryFilter||r.category===categoryFilter)&&(!sourceFilter||r.source===sourceFilter)),true);}
function refreshBills(){const el=$('#bill-results');if(el)el.innerHTML=filteredTable(periodRecords());}
const dialog=$('#modal');
function openModal(html,cls=''){dialog.className=cls;$('#modal-content').innerHTML=html;if(!dialog.open)dialog.showModal();}
function modalHead(title,subtitle=''){return `<div class="modal-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></div>`;}
function closeModal(){if(importState?.busy){toast('截图正在识别中，请等待完成。');return;}dialog.close();cleanupImport();}
function requireReal(continuation){if(!state.demo){continuation();return;}openModal(`${modalHead('开始自己的账本','示例账本帮助你了解轻记。开始后，将使用一个干净的账本。')}<div class="modal-body"><p class="confirm-text">清除示例记录，开始记录你的真实收支。此操作只清除示例数据。</p></div><div class="modal-footer"><button class="btn" data-action="close">继续体验</button><button class="btn primary" id="begin-real">清除示例，开始记账</button></div>`);$('#begin-real').onclick=()=>{state.records=[];state.demo=false;anchor=dateKey();state.anchor=anchor;persist();render();dialog.close();continuation();};}
function editRecord(id){requireReal(()=>openRecord(id));}
function openRecord(id){const r=id?state.records.find(r=>r.id===id):null;currentEdit=r?.id||null;editType=r?.type||'expense';openModal(`${modalHead(r?'编辑这笔账单':'记下生活的一笔','商户名称会自动匹配消费分类，你也可以随时调整。')}<form id="record-form"><div class="modal-body"><div class="type-options"><button type="button" data-edit-type="expense" class="${editType==='expense'?'active':''}">支出</button><button type="button" data-edit-type="income" class="${editType==='income'?'active':''}">收入</button></div><div class="form-grid"><label class="form-field">金额（元）<input name="amount" inputmode="decimal" placeholder="0.00" value="${r?(r.amount/100).toFixed(2):''}" required maxlength="15" autofocus></label><label class="form-field">日期<input name="date" type="date" value="${r?.date||dateKey()}" required></label><label class="form-field full">商户 / 账单名称<input name="merchant" placeholder="如：瑞幸咖啡、地铁出行、工资" value="${esc(r?.merchant||'')}" maxlength="200" required></label><label class="form-field">分类<select name="category">${categoryOptions(r?.category||'other')}</select></label><label class="form-field">支付方式<select name="source">${sourceOptions(r?.source||'manual')}</select></label><label class="form-field full">备注（选填）<input name="note" value="${esc(r?.note||'')}" maxlength="200" placeholder="为这一笔留下一点记忆"></label></div><label class="form-remember"><input type="checkbox" name="remember">记住此商户的分类，下次自动使用</label><div class="field-error" id="record-error" role="alert"></div></div><div class="modal-footer">${r?'<button type="button" class="btn danger" data-action="delete-record">删除账单</button>':''}<button type="button" class="btn" data-action="close">取消</button><button type="submit" class="btn primary">${r?'保存修改':'保存账单'}</button></div></form>`);const f=$('#record-form');f.elements.merchant.addEventListener('input',()=>{f.elements.category.value=classify(f.elements.merchant.value,editType,state.rules);});f.onsubmit=e=>{e.preventDefault();const amount=toCents(f.elements.amount.value),merchant=f.elements.merchant.value.trim();if(!amount||!validDate(f.elements.date.value)||!merchant){$('#record-error').textContent='请填写有效的商户、日期和大于 0 的金额（最多两位小数）。';return;}const record={id:currentEdit||uuid(),merchant,date:f.elements.date.value,amount,type:editType,category:f.elements.category.value,source:f.elements.source.value,note:f.elements.note.value.trim()};if(!validateRecord(record)){ $('#record-error').textContent='账单格式有误，请检查后再试。';return;}if(currentEdit)state.records=state.records.map(r=>r.id===currentEdit?record:r);else state.records.push(record);if(f.elements.remember.checked){state.rules=state.rules.filter(r=>r.keyword!==merchant);state.rules.unshift({keyword:merchant,category:record.category});}anchor=record.date;state.anchor=anchor;const ok=persist();dialog.close();render();if(ok)toast(currentEdit?'账单已更新':'已记下这一笔，生活又清楚了一点。');};}
function cleanupImport(){if(importState){importState.files.forEach(f=>URL.revokeObjectURL(f.url));importState=null;}}
function beginImport(){requireReal(()=>{cleanupImport();importState={files:[],rows:[],warnings:[],text:'',tab:'image',step:1,busy:false,source:'auto',profile:preferredOcrProfile,reference:dateKey()};renderImport();});}
function renderImport(){const s=importState;if(!s)return;const stepHtml=`<div class="import-top"><span class="step ${s.step===1?'active':''}"><b>1</b>选择截图</span><span class="step-connector"></span><span class="step ${s.step===2?'active':''}"><b>2</b>核对账单</span><span class="step-connector"></span><span class="step"><b>3</b>完成入账</span></div>`;if(s.step===1){openModal(`${modalHead('把截图，变成账单','支持微信 / 支付宝账单列表及交易详情截图，识别后请核对再入账。')}<div class="modal-body">${stepHtml}<div class="import-tabs"><button data-import-tab="image" class="${s.tab==='image'?'active':''}">账单截图</button><button data-import-tab="text" class="${s.tab==='text'?'active':''}">粘贴 / 修正文字</button></div>${s.tab==='image'?`<div class="drop-zone" id="drop-zone" role="button" tabindex="0" aria-label="选择账单截图"><div class="scan-big">${icon('scan')}</div><h3>把账单截图拖到这里，或点击上传</h3><p>支持 JPG、PNG、WEBP · 每张不超过 15 MB · 单次最多 10 张</p><span class="btn primary">${icon('image')}选择账单截图</span><input type="file" class="file-input" id="screenshot-files" accept="image/png,image/jpeg,image/webp" multiple aria-label="选择账单截图"><div style="margin-top:12px"><small>建议保留商户名称、金额与完整日期</small></div></div><div class="file-list">${s.files.map((f,i)=>`<div class="file-row"><img src="${f.url}" alt="截图缩略图"><div><strong>${esc(f.file.name)}</strong><small>${(f.file.size/1024).toFixed(0)} KB · ${esc(f.status||'等待识别')}</small></div>${s.busy?icon('refresh','busy-spin'):`<button class="icon-button" data-remove-file="${i}" aria-label="移除截图">${icon('close')}</button>`}</div>`).join('')}</div>`:`<label class="form-field">粘贴账单文字，或修正截图识别结果<textarea id="bill-text" class="ocr-text" placeholder="例如：\n微信支付\n2026年11月1日\n瑞幸咖啡 -14.90\n地铁出行 -6.00">${esc(s.text)}</textarea></label>`}<div class="import-options"><label class="form-field">支付平台<select id="import-source"><option value="auto">自动识别平台</option>${sourceOptions(s.source,false)}</select></label><label class="form-field">字体识别<select id="import-profile"><option value="auto">自动优化（较快）</option><option value="enhanced">主题字体增强（较慢）</option></select></label><label class="form-field">参考日期（截图缺失日期时使用）<input type="date" id="import-reference" value="${s.reference}"></label></div><div id="ocr-status" class="ocr-progress" role="status" aria-live="polite">${s.busy?'正在准备本地识别引擎…':''}</div><div class="field-error" id="import-error" role="alert"></div><div class="info-note">${icon('shield')}<span>图片只在当前设备中识别，不上传服务器。${isAndroidApp()?'APK 已内置中文引擎，无需联网下载。':'首次识别需下载约 6 MB 中文引擎，建议使用 Wi-Fi。'}主题字体建议选择「主题字体增强」，${isAndroidApp()?'会比较原图和清晰增强结果；所有识别账单须核对并勾选。':'会比较最多四种方案；结果分歧时会提示核对。'}艺术字、长截图和模糊文字仍可能识别错误。</span></div></div><div class="modal-footer"><span class="hint">${s.tab==='image'?`已选择 ${s.files.length} 张截图`:'支持从账单详情复制的文字'}</span><button class="btn" data-action="close" ${s.busy?'disabled':''}>取消</button><button class="btn primary" data-action="recognize" ${s.busy?'disabled':''}>${s.busy?icon('refresh','busy-spin'):icon('scan')}${s.busy?'识别中…':s.tab==='image'?'开始识别':'解析账单'}</button></div>`,'import-modal');$('#import-source').value=s.source;$('#import-profile').value=s.profile;bindDropZone();}else{renderReview(stepHtml);}}
function bindDropZone(){const drop=$('#drop-zone'),input=$('#screenshot-files');if(!drop)return;drop.onclick=e=>{if(e.target!==input&&!importState.busy)input.click();};drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click();}};input.onchange=()=>addFiles([...input.files]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');if(!importState.busy)addFiles([...e.dataTransfer.files]);};}
function syncImport(){if(!importState)return;importState.profile=$('#import-profile')?.value||importState.profile;preferredOcrProfile=importState.profile;try{localStorage.setItem('qingji-ocr-profile',preferredOcrProfile);}catch{}importState.source=$('#import-source')?.value||importState.source;importState.reference=$('#import-reference')?.value||importState.reference;if($('#bill-text'))importState.text=$('#bill-text').value;}
function addFiles(files){syncImport();const s=importState;let errors=[];for(const file of files){if(s.files.length>=10){errors.push('单次最多 10 张');break;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){errors.push('只支持 JPG、PNG、WEBP 图片');continue;}if(file.size>15*1024*1024){errors.push('单张图片不能超过 15 MB');continue;}if(s.files.some(f=>f.file.name===file.name&&f.file.size===file.size)){errors.push('已跳过重复选择的文件');continue;}s.files.push({file,url:URL.createObjectURL(file)});}renderImport();if(errors.length)$('#import-error').textContent=[...new Set(errors)].join('；');}
async function recognize(){const s=importState;syncImport();if(!validDate(s.reference)){$('#import-error').textContent='请填写有效的参考日期。';return;}s.rows=[];s.warnings=[];if(s.tab==='image'){if(!s.files.length){$('#import-error').textContent='请先选择至少一张账单截图。';return;}s.busy=true;renderImport();try{const results=await recognizeImages(s.files.map(f=>f.file),p=>{const el=$('#ocr-status');if(el)el.textContent=`第 ${p.index+1} / ${s.files.length} 张 · ${p.message}`;},{profile:s.profile,reference:s.reference,source:s.source,rules:state.rules});s.text=results.map(r=>r.text).join('\n\n');results.forEach((result,i)=>{const parsed=parseBillText(result.text,{reference:s.reference,source:s.source,rules:state.rules});if(result.reviewRequired)parsed.rows.forEach(r=>{r.needsReview=true;r.requireSelection=true;});s.rows.push(...parsed.rows);s.warnings.push(...parsed.warnings,...(result.warnings||[]).map(w=>`第 ${i+1} 张：${w}`));if(Number.isFinite(result.confidence)&&result.confidence<65)s.warnings.push(`第 ${i+1} 张截图清晰度或识别置信度较低，请仔细核对。`);if(!parsed.rows.length)s.warnings.push(`第 ${i+1} 张截图未提取到账单，请返回修正识别文字。`);});}catch(err){s.busy=false;renderImport();$('#import-error').textContent=`识别未完成：${err.message}。可切换到「粘贴 / 修正文字」继续。`;return;}s.busy=false;}else{const parsed=parseBillText(s.text,{reference:s.reference,source:s.source,rules:state.rules});s.rows=parsed.rows;s.warnings=parsed.warnings;}
if(!s.rows.length){s.tab='text';renderImport();$('#import-error').textContent=s.warnings.join(' ')||'没有可入账的记录，请检查文字。';return;}const seen=new Set(state.records.map(fingerprint));s.rows=s.rows.map(r=>{const fp=fingerprint(r),duplicate=seen.has(fp);seen.add(fp);return {...r,duplicate,selected:!duplicate&&!r.requireSelection};});s.step=2;renderImport();}
function renderReview(stepHtml){const s=importState;openModal(`${modalHead('最后核对一下，就记好了','识别结果可能有误。金额、收支方向和日期均可修改；APK 识别结果及有分歧或可信度偏低的账单默认不勾选，请核对后手动选择。')}<div class="modal-body">${stepHtml}${s.files.length?`<details class="ocr-originals"><summary>对照原始截图（${s.files.length} 张）</summary><div>${s.files.map(f=>`<figure><figcaption>${esc(f.file.name)}</figcaption><img src="${f.url}" alt="原始账单截图" loading="lazy"></figure>`).join('')}</div></details>`:''}<div class="review-summary">识别到 ${s.rows.length} 笔账单 · 疑似重复 ${s.rows.filter(r=>r.duplicate).length} 笔（已默认取消勾选）</div><div class="table-wrap"><table class="review-table"><thead><tr><th>入账</th><th class="merchant-col">商户 / 名称</th><th class="amount-col">金额（元）</th><th class="date-col">日期</th><th class="type-col">收支</th><th class="cat-col">分类</th><th class="source-col">支付方式</th></tr></thead><tbody>${s.rows.map((r,i)=>`<tr data-review-row="${i}" class="${r.duplicate?'duplicate':''}"><td><input type="checkbox" data-review-field="selected" aria-label="选择第${i+1}笔账单" ${r.selected?'checked':''}></td><td><input data-review-field="merchant" aria-label="第${i+1}笔商户" value="${esc(r.merchant)}" maxlength="200">${r.duplicate?'<small class="review-flag">疑似重复，请确认</small>':r.needsReview?'<small class="review-flag">待核对商户、日期及收支</small>':''}</td><td><input data-review-field="amount" aria-label="第${i+1}笔金额" inputmode="decimal" value="${(r.amount/100).toFixed(2)}"></td><td><input data-review-field="date" aria-label="第${i+1}笔日期" type="date" value="${r.date}"></td><td><select data-review-field="type" aria-label="第${i+1}笔收支"><option value="expense" ${r.type==='expense'?'selected':''}>支出</option><option value="income" ${r.type==='income'?'selected':''}>收入</option></select></td><td><select data-review-field="category" aria-label="第${i+1}笔分类">${categoryOptions(r.category)}</select></td><td><select data-review-field="source" aria-label="第${i+1}笔支付方式">${sourceOptions(r.source,false)}</select></td></tr>`).join('')}</tbody></table></div>${s.warnings.length?`<div class="warning-note">${[...new Set(s.warnings)].map(esc).join('<br>')}</div>`:''}<div class="field-error" id="import-error" role="alert"></div></div><div class="modal-footer"><span class="hint" id="review-total"></span><button class="btn" data-action="import-back">返回修正</button><button class="btn primary" data-action="commit-import">确认无误，导入账本</button></div>`,'import-modal');updateReviewTotal();}
function updateReviewTotal(){const s=importState,selected=s.rows.filter(r=>r.selected);$('#review-total').textContent=`已选 ${selected.length} 笔 · 支出 ¥${money(totals(selected).expense)} · 收入 ¥${money(totals(selected).income)}`;}
function commitImport(){const s=importState;const selected=s.rows.filter(r=>r.selected);if(!selected.length){$('#import-error').textContent='请至少选择一笔账单。';return;}if(selected.some(r=>!validateRecord(r))){$('#import-error').textContent='所选账单的金额、商户或日期无效，请修改后再入账。';return;}const clean=selected.map(({needsReview,dateInferred,duplicate,selected,requireSelection,...r})=>r);state.records.push(...clean);anchor=[...clean].sort((a,b)=>b.date.localeCompare(a.date))[0].date;state.anchor=anchor;const ok=persist();dialog.close();cleanupImport();render();if(ok)toast(`已导入 ${clean.length} 笔账单，并按账单日期归档。`);}
function download(content,name,type){try{if(saveWithAndroid(content,name,type))return true;}catch(error){toast(error.message);return false;}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;}
function exportCsv(){const records=periodRecords();if(!records.length){toast('当前周期没有可导出的账单。');return;}const cell=s=>'"'+String(s).replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['日期','商户','类型','金额（元）','分类','支付方式','备注'],...records.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>[r.date,r.merchant,r.type==='income'?'收入':'支出',(r.amount/100).toFixed(2),catById(r.category).name,sourceName(r.source),r.note||''])];if(download('\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),`轻记-${currentRange().start}-${currentRange().end}.csv`,'text/csv;charset=utf-8'))toast(isAndroidApp()?'请在系统窗口中选择保存位置。':'账单已导出，可用 Excel 打开。');}
function settings(){openModal(`${modalHead('把账本，安心留在身边','轻记 1.3.0 · 支持安卓手机、本地截图识别与离线记账。')}<div class="modal-body"><div class="settings-list"><div class="settings-row">${icon('download')}<div><h3>备份整个账本</h3><p>包含所有账单、分类规则和预算，建议定期保存。</p></div><button class="btn" data-action="backup">导出备份</button></div><div class="settings-row">${icon('upload')}<div><h3>恢复账本备份</h3><p>从轻记 JSON 备份恢复，预览确认后合并，自动跳过重复记录。</p></div><button class="btn" data-action="restore">选择文件</button><input type="file" id="backup-file" class="file-input" accept="application/json,.json"></div><div class="settings-row">${icon('plus')}<div><h3>${isAndroidApp()?'安卓应用与设备':'下载 Android APK'}</h3><p>${isAndroidApp()?`Android ${esc(nativeDeviceInfo()?.android||'')} · ${esc((nativeDeviceInfo()?.abis||[]).join(', '))} · ARM64（64 位）· 内置中文原生识别`:'支持 ARM64（64 位）手机，也可通过浏览器安装到桌面。'}</p></div>${isAndroidApp()?'':'<a class="btn" href="./install.html">下载与安装</a>'}</div><div class="settings-row">${icon('scan')}<div><h3>截图导入小贴士</h3><p>更换过主题字体时，可在导入页选择「主题字体增强」。支持小字放大、深色背景转换和分栏文字重组；请保留完整日期并核对金额。</p></div></div>${state.demo?`<div class="settings-row">${icon('book')}<div><h3>准备好开始了吗？</h3><p>清除示例记录，开始自己的真实账本。</p></div><button class="btn" data-action="start">开始记账</button></div>`:''}</div><div class="help-copy"><h3>微信与支付宝怎样截取账单？</h3><ol><li>微信：我 → 服务 → 钱包 → 账单；支付宝：我的 → 账单。</li><li>截取账单列表或点开单笔交易详情，保留商户、日期和金额。</li><li>在轻记点击「截图导入」，选择图片，等待识别。</li><li>核对商户、收支方向、日期与分类后，确认导入。</li></ol><h3>关于离线与隐私</h3><p>${isAndroidApp()?'APK 已包含中文识别模型，无需登录，首次启动即可离线使用。账本保存在应用私有空间，卸载或清除数据前请备份。':'网页版账本保存在当前浏览器；初次使用识别需下载约 6 MB 模型与引擎，后续可使用缓存。更换浏览器或清除数据前请先备份。'}</p><p>提供安卓 APK 和可安装的网页版（PWA）。识别在本地完成，不会上传图片。网页版与 APK 的账本彼此独立，可通过 JSON 备份迁移。<br><a href="./privacy.html" class="text-link">隐私说明与开源许可 →</a><br>开发者主体、客服邮箱待补充，当前为发布候选版，尚未完成实体手机验收。</p></div><div class="privacy-tag">${icon('lock')}轻记 1.3.0 · 把生活记清楚</div></div><div class="modal-footer"><button class="btn primary" data-action="close">知道了</button></div>`);$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('备份文件不能超过 20 MB');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||data.records.length>100000||!data.records.every(validateRecord))throw Error('这不是有效的轻记备份文件');const seen=new Set(state.demo?[]:state.records.map(fingerprint)),newRows=[];for(const r of data.records){if(!seen.has(fingerprint(r))){newRows.push({...r,id:uuid(),note:String(r.note||'').slice(0,200)});seen.add(fingerprint(r));}}openModal(`${modalHead('确认恢复备份')}<div class="modal-body"><p class="confirm-text">备份包含 ${data.records.length} 笔账单，可合并 ${newRows.length} 笔，跳过重复 ${data.records.length-newRows.length} 笔。${state.demo?'当前示例账单会被清除。':'现有真实账单会保留。'}</p></div><div class="modal-footer"><button class="btn" data-action="close">取消</button><button class="btn primary" id="confirm-restore">确认恢复</button></div>`);$('#confirm-restore').onclick=()=>{if(state.demo)state.records=[];state.demo=false;state.records.push(...newRows);if(Array.isArray(data.rules))state.rules=[...data.rules.filter(r=>typeof r.keyword==='string'&&r.keyword.length<=200&&CATEGORIES.some(c=>c.id===r.category)),...state.rules];if(Number.isSafeInteger(data.budget)&&data.budget>0)state.budget=data.budget;anchor=[...state.records].sort((a,b)=>b.date.localeCompare(a.date))[0]?.date||dateKey();state.anchor=anchor;const ok=persist();dialog.close();render();if(ok)toast(`已恢复 ${newRows.length} 笔账单。`);};}catch(err){toast(`恢复失败：${err.message}`);}};}
function editBudget(){openModal(`${modalHead('给花销留一点边界','设置每月预算，帮助自己做出更从容的消费决定。')}<form id="budget-form"><div class="modal-body"><label class="form-field">每月预算（元）<input name="budget" inputmode="decimal" value="${((state.budget||500000)/100).toFixed(2)}" required></label><div id="budget-error" class="field-error"></div></div><div class="modal-footer"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">保存预算</button></div></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();const val=toCents(e.target.elements.budget.value);if(!val){$('#budget-error').textContent='请输入大于 0 的预算金额，最多两位小数。';return;}state.budget=val;const ok=persist();dialog.close();render();if(ok)toast('月预算已更新。');};}

document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;const modeButton=e.target.closest('[data-mode]');if(modeButton){mode=modeButton.dataset.mode;render();}const row=e.target.closest('[data-edit]');if(row)editRecord(row.dataset.edit);const type=e.target.closest('[data-edit-type]');if(type){editType=type.dataset.editType;document.querySelectorAll('[data-edit-type]').forEach(b=>b.classList.toggle('active',b.dataset.editType===editType));const f=$('#record-form');f.elements.category.value=classify(f.elements.merchant.value,editType,state.rules);}const tab=e.target.closest('[data-import-tab]');if(tab&&importState&&!importState.busy){syncImport();importState.tab=tab.dataset.importTab;renderImport();}const remove=e.target.closest('[data-remove-file]');if(remove&&importState&&!importState.busy){syncImport();const i=+remove.dataset.removeFile;URL.revokeObjectURL(importState.files[i].url);importState.files.splice(i,1);renderImport();}
if(!action)return;
switch(action){case 'prev':case 'next':anchor=shiftAnchor(mode,anchor,action==='prev'?-1:1);render();break;case 'today':anchor=dateKey();render();break;case 'add':editRecord();break;case 'close':closeModal();break;case 'import':beginImport();break;case 'settings':settings();break;case 'start':requireReal(()=>{dialog.close();toast('空白账本已准备好，记下第一笔吧。');});break;case 'recognize':await recognize();break;case 'import-back':importState.step=1;importState.tab='text';renderImport();break;case 'commit-import':commitImport();break;case 'export-csv':exportCsv();break;case 'backup':if(download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),`轻记-完整备份-${dateKey()}.json`,'application/json'))toast(isAndroidApp()?'请在系统窗口中保存完整备份。':'完整备份已导出，请妥善保存。');break;case 'restore':$('#backup-file').click();break;case 'budget':editBudget();break;case 'install':if(installEvent){await installEvent.prompt();installEvent=null;}else{toast('安卓 Chrome：右上角 ⋮ → 安装应用 / 添加到主屏幕。');}break;case 'delete-record':{const id=currentEdit;openModal(`${modalHead('删除这笔账单？')}<div class="modal-body"><p class="confirm-text">删除后将从统计中移除。你可以在删除前导出备份。</p></div><div class="modal-footer"><button class="btn" data-action="close">保留账单</button><button class="btn danger" id="confirm-delete">确认删除</button></div>`);$('#confirm-delete').onclick=()=>{state.records=state.records.filter(r=>r.id!==id);const ok=persist();dialog.close();render();if(ok)toast('账单已删除。');};break;}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;refreshBills();}const field=e.target.dataset.reviewField;if(field&&importState){const i=+e.target.closest('[data-review-row]').dataset.reviewRow;const r=importState.rows[i];r[field]=field==='selected'?e.target.checked:field==='amount'?toCents(e.target.value):e.target.value;if(field==='type')r.category=classify(r.merchant,r.type,state.rules);if(field==='selected')e.target.closest('tr').classList.toggle('duplicate',r.duplicate&&!r.selected);updateReviewTotal();}});
document.addEventListener('change',e=>{if(e.target.id==='filter-type'){typeFilter=e.target.value;refreshBills();}if(e.target.id==='filter-category'){categoryFilter=e.target.value;refreshBills();}if(e.target.id==='filter-source'){sourceFilter=e.target.value;refreshBills();}if(e.target.dataset.reviewField==='type'){const tr=e.target.closest('[data-review-row]');tr.querySelector('[data-review-field="category"]').value=importState.rows[+tr.dataset.reviewRow].category;}});
document.addEventListener('keydown',e=>{const row=e.target.closest('[data-edit]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();editRecord(row.dataset.edit);}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('storage',e=>{if(e.key===KEY)toast('另一个窗口已修改账本。请先导出本页未保存数据，再刷新页面。');});
hydrate();render();if(storageError)toast('本地账本暂时无法读取，请先检查或恢复备份。');
if(!isAndroidApp()&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
